//! Sprite loading. All art comes from `assets/sprites/`, generated by
//! `tools/gen_sprites.py` — regenerate there, never edit PNGs.

use anyhow::{Context, Result};
use macroquad::audio::{Sound, load_sound};
use macroquad::prelude::{FilterMode, Rect, Texture2D, load_texture};
use oxide_sim::{BuildingKind, Faction, UnitKind};

/// Every sprite the shell draws, as regions of ONE texture.
///
/// A single atlas means macroquad batches the entire world into a handful
/// of draw calls; the previous texture-per-sprite scheme flushed the batch
/// on nearly every tile and halved the framerate zoomed out.
pub struct Sprites {
    texture: Texture2D,
    /// Verb pictograms for cards and order chips, indexed by
    /// [`crate::panel::VerbIcon`].
    verb_icons: [Rect; 12],
    ground: [Rect; 6],
    rock: [Rect; 4],
    /// Skyline row of a range, indexed `w_conn * 4 + e_conn * 2 + variant`.
    peak_sky: [Rect; 8],
    peak_lone: [Rect; 2],
    peak_body: [Rect; 2],
    turret_barrel: [Rect; 3],
    rock_skirt: Rect,
    decals: [Rect; 4],
    scrap_full: Rect,
    scrap_mid: Rect,
    scrap_low: Rect,
    scrap_rich: Rect,
    muzzle_flash: Rect,
    scorch: Rect,
    wreck_pile: Rect,
    air_shadow: Rect,
    burst: Rect,
    foundry: [Rect; 3],
    turret: [Rect; 3],
    fabricator: [Rect; 3],
    flak_turret: [Rect; 3],
    bastion: [Rect; 3],
    array: [Rect; 3],
    reclaimer: [Rect; 3],
    repair_bay: [Rect; 3],
    harvester: [Rect; 3],
    harvester_scoop: [[Rect; 3]; 2],
    scaffold: [Rect; 2],
    debris: [Rect; 3],
    scuttler: [Rect; 3],
    lancer: [Rect; 3],
    sentinel: [Rect; 3],
    bombard: [Rect; 3],
    flakhound: [Rect; 3],
    stinger: [Rect; 3],
    buzzard: [Rect; 3],
    darter: [Rect; 3],
    talon: [Rect; 3],
    wisp: [Rect; 3],
}

fn faction_index(faction: Faction) -> usize {
    match faction {
        Faction::Ferrous => 0,
        Faction::Cupric => 1,
    }
}

/// Third slot of every faction-varied sprite row: the allegiance-accent
/// mask (the pixels where the two faction variants differ, grayscale).
const ACCENT: usize = 2;

/// The atlas manifest as `tools/gen_sprites.py` writes it.
type Manifest = std::collections::HashMap<String, [f32; 4]>;

/// Sprites with no faction variants: one region, one name.
const SINGLE_KEYS: [&str; 10] = [
    "rock_skirt",
    "scrap_full",
    "scrap_mid",
    "scrap_low",
    "scrap_rich",
    "muzzle_flash",
    "scorch",
    "wreck_pile",
    "air_shadow",
    "burst",
];

/// Verb pictograms, ordered to match [`crate::panel::VerbIcon`].
const VERB_ICON_KEYS: [&str; 12] = [
    "icon_stop",
    "icon_move",
    "icon_attack_move",
    "icon_attack",
    "icon_patrol",
    "icon_harvest",
    "icon_build",
    "icon_repair",
    "icon_salvage",
    "icon_cancel",
    "icon_rally",
    "icon_idle",
];

const GROUND_KEYS: [&str; 6] = [
    "ground_0", "ground_1", "ground_2", "ground_3", "ground_4", "ground_5",
];

const ROCK_KEYS: [&str; 4] = ["rock_0", "rock_1", "rock_2", "rock_3"];

/// Skyline rows, ordered `w_conn * 4 + e_conn * 2 + variant`.
const PEAK_SKY_KEYS: [&str; 8] = [
    "peak_sky_00_0",
    "peak_sky_00_1",
    "peak_sky_01_0",
    "peak_sky_01_1",
    "peak_sky_10_0",
    "peak_sky_10_1",
    "peak_sky_11_0",
    "peak_sky_11_1",
];

const PEAK_LONE_KEYS: [&str; 2] = ["peak_lone_0", "peak_lone_1"];

const PEAK_BODY_KEYS: [&str; 2] = ["peak_body_0", "peak_body_1"];

const DECAL_KEYS: [&str; 4] = ["decal_crack", "decal_plate", "decal_stain", "decal_wreck"];

const SCAFFOLD_KEYS: [&str; 2] = ["scaffold_dense", "scaffold_sparse"];

const DEBRIS_KEYS: [&str; 3] = ["debris_0", "debris_1", "debris_2"];

/// The Turret's gun is faction-varied like a unit, but belongs to no kind.
const TURRET_BARREL_STEM: &str = "turret_barrel";

/// The Harvester's dig frames hang off its own stem.
const SCOOP_SUFFIXES: [&str; 2] = ["_scoop1", "_scoop2"];

/// The atlas stem a unit kind's rows live under.
fn unit_stem(kind: UnitKind) -> &'static str {
    kind.name()
}

/// The atlas stem a building kind's rows live under. Exhaustive on
/// purpose: a new kind must say where its art is before it compiles.
fn building_stem(kind: BuildingKind) -> &'static str {
    match kind {
        BuildingKind::Foundry => "foundry",
        BuildingKind::Turret => "turret",
        BuildingKind::Fabricator => "fabricator",
        BuildingKind::FlakTurret => "flak_turret",
        BuildingKind::Bastion => "bastion",
        BuildingKind::Array => "array",
        BuildingKind::Reclaimer => "reclaimer",
        BuildingKind::RepairBay => "repair_bay",
    }
}

/// The three names every faction-varied row carries.
fn variant_keys(stem: &str, suffix: &str) -> [String; 3] {
    [
        format!("{stem}_ferrous{suffix}"),
        format!("{stem}_cupric{suffix}"),
        format!("{stem}_accent{suffix}"),
    ]
}

fn lookup(rects: &Manifest, name: &str) -> Result<Rect> {
    let [x, y, w, h] = rects
        .get(name)
        .copied()
        .with_context(|| format!("sprite {name:?} missing from atlas"))?;
    Ok(Rect::new(x, y, w, h))
}

fn pick<const N: usize>(rects: &Manifest, keys: [&str; N]) -> Result<[Rect; N]> {
    let mut out = [Rect::new(0.0, 0.0, 0.0, 0.0); N];
    for (slot, key) in out.iter_mut().zip(keys) {
        *slot = lookup(rects, key)?;
    }
    Ok(out)
}

fn variant_row(rects: &Manifest, stem: &str, suffix: &str) -> Result<[Rect; 3]> {
    let mut out = [Rect::new(0.0, 0.0, 0.0, 0.0); 3];
    for (slot, key) in out.iter_mut().zip(variant_keys(stem, suffix)) {
        *slot = lookup(rects, &key)?;
    }
    Ok(out)
}

/// Every kind the shell must find art for.
#[cfg(test)]
const ALL_UNIT_KINDS: [UnitKind; 11] = [
    UnitKind::Harvester,
    UnitKind::Sentinel,
    UnitKind::Scuttler,
    UnitKind::Lancer,
    UnitKind::Bombard,
    UnitKind::Flakhound,
    UnitKind::Stinger,
    UnitKind::Buzzard,
    UnitKind::Darter,
    UnitKind::Talon,
    UnitKind::Wisp,
];

#[cfg(test)]
const ALL_BUILDING_KINDS: [BuildingKind; 8] = [
    BuildingKind::Foundry,
    BuildingKind::Turret,
    BuildingKind::Fabricator,
    BuildingKind::FlakTurret,
    BuildingKind::Bastion,
    BuildingKind::Array,
    BuildingKind::Reclaimer,
    BuildingKind::RepairBay,
];

/// Every atlas key [`Sprites::load`] resolves, built from the same lists
/// and stems the loader itself uses.
#[cfg(test)]
fn atlas_keys() -> Vec<String> {
    let mut keys: Vec<String> = SINGLE_KEYS
        .iter()
        .chain(VERB_ICON_KEYS.iter())
        .chain(GROUND_KEYS.iter())
        .chain(ROCK_KEYS.iter())
        .chain(PEAK_SKY_KEYS.iter())
        .chain(PEAK_LONE_KEYS.iter())
        .chain(PEAK_BODY_KEYS.iter())
        .chain(DECAL_KEYS.iter())
        .chain(SCAFFOLD_KEYS.iter())
        .chain(DEBRIS_KEYS.iter())
        .map(|key| (*key).to_string())
        .collect();
    keys.extend(variant_keys(TURRET_BARREL_STEM, ""));
    for kind in ALL_BUILDING_KINDS {
        keys.extend(variant_keys(building_stem(kind), ""));
    }
    for kind in ALL_UNIT_KINDS {
        keys.extend(variant_keys(unit_stem(kind), ""));
    }
    for suffix in SCOOP_SUFFIXES {
        keys.extend(variant_keys(unit_stem(UnitKind::Harvester), suffix));
    }
    keys
}

/// Where game data lives. A macOS .app bundle keeps it in
/// Contents/Resources beside `Contents/MacOS/<exe>`; development runs
/// from the workspace root. Resolved once by probing for the atlas —
/// the one file no build ships without.
pub fn resource_root() -> std::path::PathBuf {
    // Native automation runs from an isolated writable directory so
    // local replays and screenshots cannot perturb a golden walk. It
    // points back at the read-only workspace resources explicitly.
    if let Some(root) = std::env::var_os("OXIDE_RESOURCE_ROOT") {
        return root.into();
    }
    if let Ok(exe) = std::env::current_exe()
        && let Some(dir) = exe.parent()
    {
        let bundled = dir.join("../Resources");
        if bundled.join("assets/sprites/atlas.png").exists() {
            return bundled;
        }
    }
    std::path::PathBuf::from(".")
}

/// A resource path as a string macroquad's loaders accept.
pub fn resource(rel: &str) -> String {
    resource_root().join(rel).to_string_lossy().into_owned()
}

impl Sprites {
    /// Loads the atlas up front; a missing or incomplete atlas is a
    /// startup error, not a mid-game pop.
    pub async fn load() -> Result<Self> {
        let texture = load_texture(&resource("assets/sprites/atlas.png"))
            .await
            .context("loading assets/sprites/atlas.png (run from the workspace root)")?;
        texture.set_filter(FilterMode::Linear);
        let manifest = macroquad::file::load_string(&resource("assets/sprites/atlas.json"))
            .await
            .context("loading assets/sprites/atlas.json")?;
        let rects: Manifest = serde_json::from_str(&manifest).context("parsing atlas manifest")?;
        let [
            rock_skirt,
            scrap_full,
            scrap_mid,
            scrap_low,
            scrap_rich,
            muzzle_flash,
            scorch,
            wreck_pile,
            air_shadow,
            burst,
        ] = pick(&rects, SINGLE_KEYS)?;
        let unit = |kind| variant_row(&rects, unit_stem(kind), "");
        let building = |kind| variant_row(&rects, building_stem(kind), "");
        Ok(Self {
            texture,
            verb_icons: pick(&rects, VERB_ICON_KEYS)?,
            ground: pick(&rects, GROUND_KEYS)?,
            rock: pick(&rects, ROCK_KEYS)?,
            peak_sky: pick(&rects, PEAK_SKY_KEYS)?,
            peak_lone: pick(&rects, PEAK_LONE_KEYS)?,
            peak_body: pick(&rects, PEAK_BODY_KEYS)?,
            turret_barrel: variant_row(&rects, TURRET_BARREL_STEM, "")?,
            rock_skirt,
            decals: pick(&rects, DECAL_KEYS)?,
            scrap_full,
            scrap_mid,
            scrap_low,
            scrap_rich,
            muzzle_flash,
            scorch,
            wreck_pile,
            air_shadow,
            burst,
            foundry: building(BuildingKind::Foundry)?,
            turret: building(BuildingKind::Turret)?,
            fabricator: building(BuildingKind::Fabricator)?,
            flak_turret: building(BuildingKind::FlakTurret)?,
            bastion: building(BuildingKind::Bastion)?,
            array: building(BuildingKind::Array)?,
            reclaimer: building(BuildingKind::Reclaimer)?,
            repair_bay: building(BuildingKind::RepairBay)?,
            harvester: unit(UnitKind::Harvester)?,
            harvester_scoop: [
                variant_row(&rects, unit_stem(UnitKind::Harvester), SCOOP_SUFFIXES[0])?,
                variant_row(&rects, unit_stem(UnitKind::Harvester), SCOOP_SUFFIXES[1])?,
            ],
            scaffold: pick(&rects, SCAFFOLD_KEYS)?,
            debris: pick(&rects, DEBRIS_KEYS)?,
            scuttler: unit(UnitKind::Scuttler)?,
            lancer: unit(UnitKind::Lancer)?,
            sentinel: unit(UnitKind::Sentinel)?,
            bombard: unit(UnitKind::Bombard)?,
            flakhound: unit(UnitKind::Flakhound)?,
            stinger: unit(UnitKind::Stinger)?,
            buzzard: unit(UnitKind::Buzzard)?,
            darter: unit(UnitKind::Darter)?,
            talon: unit(UnitKind::Talon)?,
            wisp: unit(UnitKind::Wisp)?,
        })
    }

    /// The one texture every sprite lives in.
    pub fn texture(&self) -> &Texture2D {
        &self.texture
    }

    /// A verb pictogram's atlas region.
    pub fn verb_icon(&self, icon: crate::panel::VerbIcon) -> Rect {
        self.verb_icons[icon as usize]
    }

    /// A ground variant's atlas region.
    pub fn ground(&self, variant: usize) -> Rect {
        self.ground[variant % self.ground.len()]
    }

    /// A rock variant's atlas region.
    pub fn rock(&self, variant: usize) -> Rect {
        self.rock[variant % self.rock.len()]
    }

    /// The turret's rotating gun, per faction.
    pub fn turret_barrel(&self, faction: oxide_sim::Faction) -> Rect {
        self.turret_barrel[match faction {
            oxide_sim::Faction::Ferrous => 0,
            oxide_sim::Faction::Cupric => 1,
        }]
    }

    /// The skyline row of a mountain range: crests against open sky.
    /// `w_conn`/`e_conn` say whether the ridge continues into the
    /// neighboring tile on that side; connected sides meet the edge at
    /// a fixed height so adjacent tiles join without a seam.
    pub fn peak_sky(&self, w_conn: bool, e_conn: bool, variant: usize) -> Rect {
        self.peak_sky[(w_conn as usize) * 4 + (e_conn as usize) * 2 + (variant % 2)]
    }

    /// A single standing peak with inset feet.
    pub fn peak_lone(&self, variant: usize) -> Rect {
        self.peak_lone[variant % self.peak_lone.len()]
    }

    /// Interior of a mountain wall: solid rock, seamless on every edge.
    pub fn peak_body(&self, variant: usize) -> Rect {
        self.peak_body[variant % self.peak_body.len()]
    }

    /// The soft shadow a rock casts on a neighboring ground tile
    /// (authored falling from the top edge; rotate toward the rock).
    pub fn rock_skirt(&self) -> Rect {
        self.rock_skirt
    }

    /// A ground decal's atlas region.
    pub fn decal(&self, variant: usize) -> Rect {
        self.decals[variant % self.decals.len()]
    }

    /// The scrap sprite region for a remaining amount: anything above a
    /// standard node renders as the rich pile, then thirds of standard.
    pub fn scrap(&self, amount: u32, standard_amount: u32) -> Rect {
        if amount > standard_amount {
            self.scrap_rich
        } else if amount * 3 > standard_amount * 2 {
            self.scrap_full
        } else if amount * 3 > standard_amount {
            self.scrap_mid
        } else {
            self.scrap_low
        }
    }

    /// The muzzle-flash atlas region.
    pub fn muzzle_flash(&self) -> Rect {
        self.muzzle_flash
    }

    /// The building-death scorch decal region.
    pub fn scorch(&self) -> Rect {
        self.scorch
    }

    /// A wreck salvage pile on open ground.
    pub fn wreck_pile(&self) -> Rect {
        self.wreck_pile
    }

    /// The soft shadow a flyer casts on the ground.
    pub fn air_shadow(&self) -> Rect {
        self.air_shadow
    }

    /// The splash-detonation frame.
    pub fn burst(&self) -> Rect {
        self.burst
    }

    /// The building sprite region for a kind and faction.
    fn building_row(&self, kind: oxide_sim::BuildingKind) -> &[Rect; 3] {
        match kind {
            oxide_sim::BuildingKind::Foundry => &self.foundry,
            oxide_sim::BuildingKind::Turret => &self.turret,
            oxide_sim::BuildingKind::Fabricator => &self.fabricator,
            oxide_sim::BuildingKind::FlakTurret => &self.flak_turret,
            oxide_sim::BuildingKind::Bastion => &self.bastion,
            oxide_sim::BuildingKind::Array => &self.array,
            oxide_sim::BuildingKind::Reclaimer => &self.reclaimer,
            oxide_sim::BuildingKind::RepairBay => &self.repair_bay,
        }
    }

    pub fn building(&self, kind: oxide_sim::BuildingKind, faction: Faction) -> Rect {
        self.building_row(kind)[faction_index(faction)]
    }

    /// The allegiance-accent mask over a building's faction-colored
    /// regions — grayscale in the atlas, tinted at draw time.
    pub fn building_accent(&self, kind: oxide_sim::BuildingKind) -> Rect {
        self.building_row(kind)[ACCENT]
    }

    /// A working harvester's scoop-cycle frame: 0 is the travel pose,
    /// 1-2 the dig. Values past 2 are the caller's cycle math leaking.
    pub fn harvester_working(&self, faction: Faction, frame: usize) -> Rect {
        let f = faction_index(faction);
        match frame {
            0 => self.harvester[f],
            1 => self.harvester_scoop[0][f],
            _ => self.harvester_scoop[1][f],
        }
    }

    /// The scoop cycle's accent mask, frame-matched to
    /// [`Self::harvester_working`].
    pub fn harvester_working_accent(&self, frame: usize) -> Rect {
        match frame {
            0 => self.harvester[ACCENT],
            1 => self.harvester_scoop[0][ACCENT],
            _ => self.harvester_scoop[1][ACCENT],
        }
    }

    /// The construction lattice: dense early, sparse near completion.
    pub fn scaffold(&self, dense: bool) -> Rect {
        self.scaffold[if dense { 0 } else { 1 }]
    }

    /// A death-scatter hull shard.
    pub fn debris(&self, variant: usize) -> Rect {
        self.debris[variant % 3]
    }

    fn unit_row(&self, kind: UnitKind) -> &[Rect; 3] {
        match kind {
            UnitKind::Harvester => &self.harvester,
            UnitKind::Sentinel => &self.sentinel,
            UnitKind::Scuttler => &self.scuttler,
            UnitKind::Lancer => &self.lancer,
            UnitKind::Bombard => &self.bombard,
            UnitKind::Flakhound => &self.flakhound,
            UnitKind::Stinger => &self.stinger,
            UnitKind::Buzzard => &self.buzzard,
            UnitKind::Darter => &self.darter,
            UnitKind::Talon => &self.talon,
            UnitKind::Wisp => &self.wisp,
        }
    }

    /// The unit sprite region for a kind and faction.
    pub fn unit(&self, kind: UnitKind, faction: Faction) -> Rect {
        self.unit_row(kind)[faction_index(faction)]
    }

    /// The allegiance-accent mask over a unit's faction-colored
    /// regions — grayscale in the atlas, tinted at draw time.
    pub fn unit_accent(&self, kind: UnitKind) -> Rect {
        self.unit_row(kind)[ACCENT]
    }

    /// The turret barrel's accent mask.
    pub fn turret_barrel_accent(&self) -> Rect {
        self.turret_barrel[ACCENT]
    }
}

/// Every clip the shell plays. Generated by `tools/gen_sounds.py`.
pub struct Sounds {
    /// An attack landing.
    pub laser: Sound,
    /// A Lancer's rail shot.
    pub rail_fire: Sound,
    /// A unit popping.
    pub unit_death: Sound,
    /// A building coming down.
    pub building_boom: Sound,
    /// Your harvester delivering.
    pub deposit: Sound,
    /// Your Foundry finishing a unit.
    pub train_done: Sound,
    /// Menu activation.
    pub click: Sound,
    /// An order was refused.
    pub denied: Sound,
    /// You won.
    pub victory: Sound,
    /// You didn't.
    pub defeat: Sound,
    /// Flak bursting against the sky.
    pub flak: Sound,
    /// An artillery shell landing.
    pub artillery_boom: Sound,
    /// The gun speaking (the boom belongs to the impact).
    pub artillery_launch: Sound,
    /// Order acknowledged.
    pub ack: Sound,
    /// The zap's lower sibling, alternated per shot.
    pub laser2: Sound,
}

async fn clip(name: &str) -> Result<Sound> {
    let path = resource(&format!("assets/sounds/{name}.wav"));
    load_sound(&path)
        .await
        .with_context(|| format!("loading {path} (run from the workspace root)"))
}

impl Sounds {
    /// Loads every clip up front, like [`Sprites::load`].
    pub async fn load() -> Result<Self> {
        Ok(Self {
            laser: clip("laser").await?,
            rail_fire: clip("rail_fire").await?,
            unit_death: clip("unit_death").await?,
            building_boom: clip("building_boom").await?,
            deposit: clip("deposit").await?,
            train_done: clip("train_done").await?,
            click: clip("click").await?,
            denied: clip("denied").await?,
            victory: clip("victory").await?,
            defeat: clip("defeat").await?,
            flak: clip("flak").await?,
            artillery_boom: clip("artillery_boom").await?,
            artillery_launch: clip("artillery_launch").await?,
            ack: clip("ack").await?,
            laser2: clip("laser2").await?,
        })
    }
}

/// The asset manifest, checked without a GPU.
///
/// [`Sprites::load`] already fails loudly on a missing region and
/// [`Sprites::unit_row`] is exhaustive, so a new kind cannot compile
/// without a sprite row — but both of those checks need a window, which
/// CI never opens. These read `atlas.json` as plain data instead, so a
/// regenerated atlas that dropped a row, or a kind whose art was never
/// generated, fails by name in the ordinary test run.
#[cfg(test)]
mod tests {
    use super::*;

    fn manifest() -> Manifest {
        let path =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../assets/sprites/atlas.json");
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("reading {}: {err}", path.display()));
        serde_json::from_str(&text).expect("atlas.json maps names to [x, y, w, h]")
    }

    #[test]
    fn the_shell_and_the_atlas_name_the_same_sprites() {
        let atlas = manifest();
        let named = atlas_keys();
        let mut missing: Vec<&String> = named.iter().filter(|k| !atlas.contains_key(*k)).collect();
        missing.sort();
        assert!(
            missing.is_empty(),
            "the shell asks for sprites the atlas does not ship: {missing:?} \
             — regenerate with tools/gen_sprites.py"
        );
        // The other direction: art nothing draws is art nobody blessed.
        // gen_sprites.py and the shell ship together, so a row with no
        // reader is a half-landed change, not a spare part.
        let mut orphans: Vec<&String> = atlas.keys().filter(|k| !named.contains(k)).collect();
        orphans.sort();
        assert!(
            orphans.is_empty(),
            "the atlas ships sprites the shell never draws: {orphans:?}"
        );
        // Containment both ways still allows the shell to name one
        // region twice; a bijection does not.
        assert_eq!(named.len(), atlas.len(), "a sprite is named twice");
    }

    #[test]
    fn every_kind_has_both_rosters_and_an_accent_mask() {
        let atlas = manifest();
        let stems = ALL_UNIT_KINDS
            .map(unit_stem)
            .into_iter()
            .chain(ALL_BUILDING_KINDS.map(building_stem));
        for stem in stems {
            for key in variant_keys(stem, "") {
                assert!(atlas.contains_key(&key), "no {key} in the atlas");
            }
        }
    }
}
